<template>
  <div class="topLeft">
    <el-row>
      <el-col :span="18"><div class="bg-purple">统一待办</div></el-col>
      <el-col :span="6">
        <div @click="gotoTaskCenter">
          <img class="moreImg" src="../assets/icon_2all_a.png"/>
          <span class="moreTitle">更多</span>
        </div>
      </el-col>
    </el-row>
    <el-table :data="taskList" style="width: 100%;" @row-click="openTask" :show-header="false"
              :row-style="{'height': '30px','cursor':'pointer'}"
              :cell-style="{'padding':'6px 0px'}"
              empty-text="您的工作已经处理完了"
    >
      <el-table-column label="" width="10">•</el-table-column>
      <el-table-column prop="title" label="标题"></el-table-column>
      <el-table-column prop="startTime" label="到达时间" width="100" :formatter="formatterTime"></el-table-column>
    </el-table>
  </div>
  <div class="topRight">
    <el-row>
      <el-col :span="18"><div class="bg-purple">{{ appName }}</div></el-col>
      <el-col :span="6">
        <div @click="openCMS">
          <img class="moreImg" src="../assets/icon_2all_a.png"/>
          <span class="moreTitle">更多</span>
        </div>
      </el-col>
    </el-row>
    <div class="itemContentDiv" v-for="document in documentList" @click="openDocument(document.id)">
      <div class="itemTitle">{{document.title}}</div>
      <div class="itemBody">{{document.summary}} ...【详情】</div>
    </div>
    <el-empty v-if="documentList.length<=0" :image-size="80" description="暂无数据"></el-empty>
  </div>
</template>

<script setup>
import {ref} from 'vue'
import {o2} from '@o2oa/component'

const documentList = ref([]);
const documentList2 = ref([]);
const props = defineProps({
  appName: String
})
o2.Actions.load("x_cms_assemble_control").DocumentAction.	query_listWithFilterPaging(1,3,{"appNameList":[props.appName]}).then((json)=>{
  documentList.value = json.data;
});
const taskList = ref([]);
o2.Actions.load("x_processplatform_assemble_surface").TaskAction.V2ListPaging(1, 5).then((json)=>{
  taskList.value = json.data;
});
function openTask(row,column,e){
  o2.api.page.openWork(row.work);
}
function openDocument(id){
  o2.api.page.openDocument(id);
}
function openCMS(){
  o2.api.page.openCMS(props.appName);
}
function gotoTaskCenter(){
  o2.api.page.openApplication("process.workcenter");
}
function formatterTime(row, column) {
  let data = row[column.property]
  return /\d{4}-\d{1,2}-\d{1,2}/g.exec(data)
}
</script>

<style scoped>
.topLeft{
  float: left;
  margin: 0px;
  min-height: 320px;
  width: 538px;
  background-color: #FFFFFF;
  overflow: hidden;
}
.topRight{
  margin-left: 553px;
  min-height: 320px;
  background-color: #FFFFFF;
}
.moreTitle{
  float: right;
  font-szie: 12px;
  color: #4A90E2;
  margin-right: 10px;
  margin-top: 12px;
  cursor: pointer;
}
.moreImg{
  float: right;
  margin-top: 14px;
  margin-right: 20px;
}
.itemContentDiv{
  border-bottom: 1px solid #dddddd;
  cursor: pointer;
  text-align: left;
}
.itemTitle{
  font-size: 16px;
  height: 30px;
  line-height: 30px;
  color: #333333;
  padding-left: 10px;
  margin: 7px 0px 5px 0px;
  cursor: pointer;
}
.itemBody{
  font-size: 12px;
  color: #666666;
  padding: 0px 15px;
  overflow: hidden;
  height: 40px;
  line-height: 20px;
  margin-bottom: 8px;
}
.el-row {
  height: 40px;
  background: #F7F7F7;
}
.bg-purple {
  text-align: left;
  line-height: 40px;
  font-size: 16px;
  color: #333333;
  padding-left: 10px;
  font-weight: bold;
}
</style>