<template>
  <div class="topLeft">
    <HotPic/>
  </div>
  <div class="topRight">
    <el-row>
      <el-col :span="18"><div class="bg-purple">{{ appName }}</div></el-col>
      <el-col :span="6">
        <div @click="openCMS">
          <img class="moreImg" src="../assets/icon_2all_a.png"/>
          <span class="moreTitle">更多</span>
        </div>
      </el-col>
    </el-row>
    <el-table :data="documentList" style="width: 100%;" @row-click="openDocument" :show-header="false"
              :row-style="{'height': '30px','cursor':'pointer'}"
              :cell-style="{'padding':'6px 0px'}"
              empty-text="暂无数据"
    >
      <el-table-column label="" width="10">•</el-table-column>
      <el-table-column prop="title" label="标题"></el-table-column>
      <el-table-column prop="categoryName" label="分类" width="80"></el-table-column>
      <el-table-column prop="publishTime" label="发布时间" width="100" :formatter="formatterTime"></el-table-column>
    </el-table>
  </div>
</template>

<script setup>
import {ref} from 'vue'
import {o2} from '@o2oa/component'
import HotPic from "@/components/HotPic";

const props = defineProps({
  appName: String
})

const documentList = ref([]);

o2.Actions.load("x_cms_assemble_control").DocumentAction.	query_listWithFilterPaging(1,6,{"appNameList":[props.appName]}).then((json)=>{
  documentList.value = json.data;
});

function openDocument(row,column,e){
  o2.api.page.openDocument(row.id);
}
function openCMS(){
  o2.api.page.openCMS(props.appName);
}
function formatterTime(row, column) {
  let data = row[column.property]
  return /\d{4}-\d{1,2}-\d{1,2}/g.exec(data)
}
</script>

